    ('46d5879d-235f-5639-91b0-04bd08c2f70f'::uuid, 'Les temps'),
    ('edf767d9-8938-515b-b743-791df5954739'::uuid, 'Les temps'),
    ('fb3d717b-259a-5201-ac3a-3771771dc1b6'::uuid, 'Les temps'),
