-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('99fe0786-8e8e-5215-84c3-4785d29407f3'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, 'Pourquoi écrit-on « an hour » et non « a hour » ?', 'mcq', '["Parce que le h ne se prononce pas","Parce que « hour » est un nom abstrait","Parce que le mot commence par une consonne écrite","Parce que c’est une exception sans règle"]'::jsonb, 0, 'Le choix a/an dépend du SON initial, pas de la lettre.', 1),
    ('9c98f7af-cf7c-544d-8f2d-99a8ddb14bba'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, 'On écrit « a university » et non « an university ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le mot commence par le son /j/ (« you »), donc « a ».', 2),
    ('f2809ec4-0444-5663-9635-9191041d4c0c'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, 'Comment traduit-on « La vie est dure » ?', 'mcq', '["Life is hard","The life is hard","A life is hard","The life is the hard"]'::jsonb, 0, 'Un nom pris au sens général ne prend pas d’article en anglais.', 3),
    ('6772c370-fb68-5f67-88f2-30ab6c68d548'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, '« The » s’emploie devant les noms de pays au pluriel comme *the Netherlands*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De même *the United States*, *the Philippines*.', 4),
    ('da3ec583-c238-555e-8f7d-3436b2bb4aef'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, 'Le génitif de « les sacs des étudiants » s’écrit…', 'mcq', '["the students’ bags","the students’s bags","the student’s bags","the bags of students"]'::jsonb, 0, 'Un pluriel déjà en -s ne prend que l’apostrophe.', 5),
    ('56e1ae7a-67d1-5f09-b968-2eedbe33ab32'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, 'Dans « his sister », le possessif s’accorde avec…', 'mcq', '["Le possesseur","L’objet possédé","Le verbe","Le sujet de la phrase suivante"]'::jsonb, 0, 'C’est un frère ou une sœur DE LUI : *his*, quel que soit le genre de « sister ».', 6),
    ('04c29566-756d-53b2-b3e3-c2b9b13bc6c0'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, '« These » désigne ce qui est éloigné dans l’espace ou le temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*These* est proche ; *those* est éloigné.', 7),
    ('18882e11-ec01-5414-95cf-c812e719a507'::uuid, 'f0cc6e2c-18d1-5cd9-9627-862cde7121c7'::uuid, 'Devant un superlatif, on emploie…', 'mcq', '["the","a","an","aucun article"]'::jsonb, 0, '*She is the best student in the class.*', 8),
    ('e71c2917-4240-572e-ab93-536092cab207'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, 'Quel quantifieur s’emploie avec un indénombrable ?', 'mcq', '["much","many","a few","several"]'::jsonb, 0, '*Much money*, mais *many books*.', 1),
    ('5b5b7a10-cf49-52e5-9eaf-d89030eeebfc'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, '« A few friends » signifie « très peu d’amis, presque aucun ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*A few* est positif (« quelques ») ; c’est *few* qui est négatif.', 2),
    ('50b5877c-3538-5ad6-8ea1-0aa609a38217'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, 'Comment traduit-on « un conseil » ?', 'mcq', '["A piece of advice","An advice","A advice","One advice"]'::jsonb, 0, '*Advice* est indénombrable : il passe par *a piece of*.', 3),
    ('27b2d644-ccf9-5b1c-a57e-7274a5ebddd7'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, 'Dans une question, on emploie normalement…', 'mcq', '["any","some","much of","a lot"]'::jsonb, 0, '*Have you got any money?* — *some* reste possible pour une offre.', 4),
    ('105d4eb6-f8a5-5d44-9ef9-81ae9dd5f54f'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, '« The news is good » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*News* est un indénombrable singulier malgré son -s.', 5),
    ('08e25984-c177-55d3-bfdb-5acc8b615844'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, 'Où se place « enough » avec un adjectif ?', 'mcq', '["Après l’adjectif : old enough","Avant l’adjectif : enough old","En fin de phrase uniquement","Avant le verbe"]'::jsonb, 0, 'Mais devant un nom il précède : *enough time*.', 6),
    ('4ffd3d26-e792-5d81-a8e1-7336ef3366ff'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, '« Too much homework » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Homework* est indénombrable, donc *much* et pas *many*.', 7),
    ('7441b741-761e-5d40-9afb-1a0d5c8132e4'::uuid, 'b0c655e1-9d75-5474-81f2-922e8be2928a'::uuid, '« Any student can apply » signifie…', 'mcq', '["N’importe quel étudiant peut postuler","Aucun étudiant ne peut postuler","Quelques étudiants postulent","Tous les étudiants ont postulé"]'::jsonb, 0, 'À l’affirmative, *any* prend le sens de « n’importe lequel ».', 8),
    ('115a6a0d-ef84-519d-9714-39e7e29cecd5'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, 'Comment traduit-on « de grands bâtiments » ?', 'mcq', '["Tall buildings","Talls buildings","Buildings tall","Tall buildingses"]'::jsonb, 0, 'L’adjectif est invariable et se place avant le nom.', 1),
    ('6559be00-f9a1-54d6-b63f-de399e9dba5a'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, '« I am boring » signifie…', 'mcq', '["Je suis ennuyeux","Je m’ennuie","Je suis fatigué","Je suis pressé"]'::jsonb, 0, 'Pour « je m’ennuie », il faut *I am bored*.', 2),
    ('782ddd55-e35a-5924-ae77-ff599c0fd270'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, 'L’adjectif en -ing décrit ce qui provoque l’émotion.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Interesting* provoque, *interested* ressent.', 3),
    ('59f2814e-519f-5762-bd03-0e2561e49370'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, 'Quel est l’ordre correct ?', 'mcq', '["A big red Italian car","A red big Italian car","An Italian red big car","A red Italian big car"]'::jsonb, 0, 'Taille, puis couleur, puis origine.', 4),
    ('d46149f3-e26a-5173-8c0f-31c9c3683b1c'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, 'Après « seem », l’adjectif reste attribut du sujet.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*She seems happy* — comme après *be*, *look*, *feel*.', 5),
    ('116f0d43-5b17-5c48-b5d2-a72d44ffafff'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, '« The unemployed » désigne…', 'mcq', '["Les chômeurs, comme groupe","Un chômeur","Le chômage","Le licenciement"]'::jsonb, 0, '*The* + adjectif désigne l’ensemble d’un groupe.', 6),
    ('bcd3c5a4-12d6-51c9-aa59-c7ecf76bcf76'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, '« The rich is getting richer » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’adjectif substantivé est pluriel : *the rich ARE getting richer*.', 7),
    ('0a727526-66e2-55d9-973b-a140b47f8aa3'::uuid, '01d2956e-01c8-5dd0-be75-9f3a39bb26ac'::uuid, 'Un adjectif anglais s’accorde en nombre avec le nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est toujours invariable, quelle que soit sa place.', 8),
    ('c4ae0d96-26df-5840-a148-7d16432a9d5e'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, 'Dans « The house was built in 1920 », « was » est…', 'mcq', '["Un auxiliaire du passif","Un verbe lexical signifiant « être »","Un modal","Un auxiliaire du present perfect"]'::jsonb, 0, '*Be* + participe passé = voix passive.', 1),
    ('09880e29-7eff-5c0d-a33e-cca4b1c0596f'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, 'Comment traduit-on « J’ai froid » ?', 'mcq', '["I am cold","I have cold","I have got cold","It makes me cold"]'::jsonb, 0, 'L’anglais emploie *be* là où le français emploie « avoir ».', 2),
    ('b6fc8208-e890-57b7-a27b-115a4c132a45'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, '« Like you tea? » est une question correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans auxiliaire, il faut en fabriquer un : *Do you like tea?*', 3),
    ('59ec4b0c-1498-5185-b4ae-7ecd9111f335'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, 'Dans « I DO like it », l’auxiliaire sert à…', 'mcq', '["Insister","Poser une question","Nier","Former un passé"]'::jsonb, 0, 'C’est l’emphase, souvent pour contredire.', 4),
    ('89961188-b91c-5b41-8053-1ca7c79cfbd1'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, 'Dans « I have a car », « have » est un verbe lexical.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il signifie « posséder » et n’aide aucun autre verbe.', 5),
    ('378fffc3-094e-5ff4-a680-db2d0dd1c2ce'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, 'Quel élément porte la négation dans une phrase anglaise ?', 'mcq', '["L’auxiliaire","Le verbe lexical","Le sujet","Le complément"]'::jsonb, 0, '*I do not know*, *she has not finished*.', 6),
    ('ee0bb7b1-ff2d-51b0-b758-c7e19158c908'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, '« Have breakfast » signifie « posséder un petit-déjeuner ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ici *have* signifie « prendre ».', 7),
    ('81ee2d73-56c8-53a3-9f7c-43780f848edc'::uuid, 'ea4e65d8-cb4e-536b-abc4-edd8ef218485'::uuid, 'Dans un question tag, on reprend…', 'mcq', '["L’auxiliaire de la phrase","Le verbe lexical","Le sujet seul","Un mot interrogatif"]'::jsonb, 0, '*You like it, don’t you?* — l’auxiliaire est fabriqué si besoin.', 8),
    ('0c069b0f-33ee-5ee6-a883-fc0dc493e9d1'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, 'Quelle forme suit un modal ?', 'mcq', '["La base verbale sans TO","L’infinitif avec TO","Le participe présent","Le prétérit"]'::jsonb, 0, '*He can swim*, jamais *he can to swim*.', 1),
    ('61811cfa-f50e-5584-9317-95df1bfb576b'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, '« He cans swim » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un modal ne prend jamais de -s à la 3e personne.', 2),
    ('1fb84538-c476-5911-8300-481f0c694f77'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, '« You mustn’t go » signifie…', 'mcq', '["Tu ne dois pas y aller : c’est interdit","Tu n’es pas obligé d’y aller","Tu devrais y aller","Tu pourras y aller"]'::jsonb, 0, 'L’absence d’obligation, c’est *you don’t have to go*.', 3),
    ('16d55a39-14e3-585c-8a92-efccd63b9fc3'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, '« He must be tired » exprime ici…', 'mcq', '["Une déduction","Une obligation","Une permission","Une capacité passée"]'::jsonb, 0, 'C’est la valeur épistémique de *must*.', 4),
    ('c58793ed-8040-57f0-b6d8-51e105c8e175'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, '« He will can come » est une forme correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Deux modaux ne se suivent pas : *he will be able to come*.', 5),
    ('dbf40b33-152e-5736-a3f7-625e4a2bd1cb'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, '« She should have called » exprime…', 'mcq', '["Un reproche sur le passé","Une obligation future","Une capacité","Une permission"]'::jsonb, 0, 'Modal + *have* + participe passé porte un regard sur le passé.', 6),
    ('8c5e6d71-78ec-5033-a746-18411b154c84'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, 'Quelle différence entre « must » et « have to » ?', 'mcq', '["Must vient du locuteur, have to des circonstances","Must est toujours passé","Have to est un modal","Aucune différence"]'::jsonb, 0, 'D’où *I must stop smoking* (ma décision) vs *I have to work late* (on m’y oblige).', 7),
    ('72b91932-a7b8-5357-a3a7-807dee48872b'::uuid, '9ae095f7-1661-58be-88c9-9b5b8064eccc'::uuid, '« It might rain » exprime une possibilité incertaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*May* et *might* marquent l’éventualité.', 8),
    ('b4167dff-2857-59c2-9f1d-beecf173edee'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, 'Que signifie « give up » ?', 'mcq', '["Abandonner","Donner","Se lever","Rendre visite"]'::jsonb, 0, 'La particule change complètement le sens du verbe.', 1),
    ('9c47d187-c7f3-5ed9-889d-4a4e9850f117'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, '« Turn on it » est correct pour « allume-la ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un pronom s’intercale obligatoirement : *turn it on*.', 2),
    ('740ccb63-62de-5a5d-a153-6187189fdaee'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, 'Que signifie « look after » ?', 'mcq', '["S’occuper de","Chercher","Regarder","Ressembler à"]'::jsonb, 0, '*Look for* = chercher, *look at* = regarder.', 3),
    ('1049c9e6-8ece-525c-ae2f-b2104002568c'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, 'Dans un verbe prépositionnel, le complément peut s’intercaler.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La préposition est inséparable : *listen to the radio*.', 4),
    ('18dc90ac-9355-547e-865b-45489c0959cb'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, '« I look forward to hearing from you » se termine par un gérondif parce que…', 'mcq', '["« to » y est une préposition, pas la marque de l’infinitif","C’est une exception","Le verbe est irrégulier","La phrase est au passif"]'::jsonb, 0, 'Après une préposition, l’anglais met toujours la forme en -ING.', 5),
    ('1a4bf622-a865-54be-9255-923442b30daf'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, '« Who are you waiting for? » est une phrase correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La préposition peut rester en fin de phrase, contrairement au français.', 6),
    ('2df2d297-3c3e-5274-8ab8-635bc4ae222f'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, 'Que signifie « put off » ?', 'mcq', '["Reporter","Poser","Éteindre le feu","Se déshabiller"]'::jsonb, 0, '*The meeting was put off until Monday.*', 7),
    ('4882188f-ed45-5db3-8c11-e1e1e80ccbc1'::uuid, 'd8b573f3-072e-5e92-ab8e-ad45d7c4c9bb'::uuid, '« Look up a word » signifie…', 'mcq', '["Chercher un mot dans un dictionnaire","Lever les yeux vers un mot","Épeler un mot","Souligner un mot"]'::jsonb, 0, 'Encore une particule qui refait le sens du verbe.', 8),
    ('a462be13-1d49-5036-ae26-ac17b117dcb1'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, 'Quelle forme suit une préposition ?', 'mcq', '["La forme en -ING","L’infinitif avec TO","La base verbale","Le participe passé"]'::jsonb, 0, '*Before leaving*, *good at singing*.', 1),
    ('0335ceae-d85d-54bb-be09-f8a8fe8058f8'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, '« I look forward to see you » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ici *to* est une préposition : *to seeing you*.', 2),
    ('b0c2e4ec-289d-56e8-b772-6c2e1b105f35'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, 'Quel verbe est suivi de -ING ?', 'mcq', '["enjoy","decide","want","promise"]'::jsonb, 0, '*I enjoy reading* ; les trois autres appellent l’infinitif.', 3),
    ('927cc6ab-a3e3-500c-bea5-1cfb7119ca58'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, '« I stopped smoking » signifie…', 'mcq', '["J’ai arrêté de fumer","Je me suis arrêté pour fumer","J’ai commencé à fumer","Je fume encore"]'::jsonb, 0, '*I stopped to smoke* signifierait l’inverse.', 4),
    ('dc73c0e3-4411-5b29-bd84-6c84859312d4'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, '« Remember doing something » renvoie au souvenir d’une action déjà faite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Remember to do* signifie au contraire « penser à faire ».', 5),
    ('0eec642e-a4f0-501f-a775-4fca8be6194e'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, 'Après « avoid », on emploie…', 'mcq', '["-ING","to + base verbale","la base verbale seule","un participe passé"]'::jsonb, 0, '*He avoided answering the question.*', 6),
    ('a73ba2a2-c8d9-5db7-bc77-4fe074f1914c'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, '« She decided leaving » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Decide* appelle l’infinitif : *decided to leave*.', 7),
    ('499c7d6d-49c1-5da0-9734-1a8404b9025e'::uuid, 'b82b2a3c-57a8-540b-95fb-a5ce829ff089'::uuid, '« Try doing » signifie…', 'mcq', '["Essayer pour voir ce que ça donne","S’efforcer difficilement","Refuser de faire","Réussir à faire"]'::jsonb, 0, '*Try to do*, lui, marque l’effort.', 8),
    ('34054ccd-919f-58d8-b3e0-c43d7dc0a691'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, 'Que signifie « hardly » ?', 'mcq', '["À peine","Durement","Difficilement","Fortement"]'::jsonb, 0, 'Faux ami classique : *I could hardly hear him.*', 1),
    ('f3150a09-e9d4-530d-a33c-a08a4fefbde4'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, 'Où se place « often » dans « She works late » ?', 'mcq', '["Avant le verbe : She often works late","En fin de phrase obligatoirement","Entre le verbe et son complément","Avant le sujet"]'::jsonb, 0, 'Les adverbes de fréquence précèdent le verbe lexical.', 2),
    ('a67e44a6-01f3-5c94-b741-ea16a433bb6a'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, '« She is often late » : l’adverbe se place après « be ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *be* et les auxiliaires, l’adverbe passe derrière.', 3),
    ('b332b40b-8800-5351-b9ee-d60a0700d41e'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, '« He speaks fluently English » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne sépare jamais le verbe de son COD : *He speaks English fluently.*', 4),
    ('575cfb6f-9d9e-5853-9f57-0612c4df5043'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, 'Quel est l’adverbe formé sur « happy » ?', 'mcq', '["happily","happyly","happly","happier"]'::jsonb, 0, 'Le -y final devient -i devant -ly.', 5),
    ('8699c80b-0fc7-5037-aef1-abb151ccc696'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, 'Comment dit-on « bien meilleur » ?', 'mcq', '["Much better","Very better","Very best","More better"]'::jsonb, 0, '*Very* ne se combine pas avec un comparatif.', 6),
    ('2aa89e8f-7a4a-5286-9128-2ea798bb871e'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, '« Fast » a la même forme comme adjectif et comme adverbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *hard*, *late*, *early*.', 7),
    ('8a8ed029-3138-5396-a21d-5520579ca506'::uuid, '78babdd5-ca0b-5605-8151-1902d312098b'::uuid, '« Lately » signifie…', 'mcq', '["Récemment","Tardivement","Lentement","Plus tard"]'::jsonb, 0, 'Pour « en retard », c’est *late*.', 8),
    ('63a22cfd-bd24-5a19-b5c6-7c7e02062a24'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, 'Quel temps pour « L’eau bout à 100 °C » ?', 'mcq', '["Le présent simple","Le présent en BE + -ING","Le prétérit","Le present perfect"]'::jsonb, 0, 'Une vérité générale appelle le présent simple.', 1),
    ('78ba481e-f5f1-5df9-83a9-fdce8bf1fcab'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, '« I am knowing the answer » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Know* est un verbe d’état : *I know the answer.*', 2),
    ('e3dd4fc7-fce5-5d97-ae28-6af311098376'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, '« She is working right now » décrit…', 'mcq', '["Une action en cours","Une habitude","Un fait permanent","Un projet abandonné"]'::jsonb, 0, 'C’est la valeur première de BE + -ING.', 3),
    ('d50ba4d3-7281-5025-97d0-b4b7d563a63f'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, '« He is always complaining » ajoute une nuance…', 'mcq', '["D’agacement","De politesse","De doute","De regret"]'::jsonb, 0, '*Always* + -ING marque l’exaspération.', 4),
    ('3fe7bb1c-28c2-5c1a-ba7c-5d92c9b2b92a'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, 'Comment traduit-on « Quand il arrivera, je t’appellerai » ?', 'mcq', '["When he arrives, I’ll call you","When he will arrive, I’ll call you","When he arrive, I call you","When he is arriving, I call you"]'::jsonb, 0, 'Après *when*, l’anglais emploie le présent, jamais *will*.', 5),
    ('4a3dafd4-f453-59a6-9f7d-0deaed520d95'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, '« We’re leaving tomorrow » exprime un futur programmé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'BE + -ING sert couramment au futur planifié.', 6),
    ('145a4983-7a9c-5b74-8643-49fa6414f7da'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, 'À la 3e personne du singulier, le présent simple prend…', 'mcq', '["-s","-ing","-ed","aucune marque"]'::jsonb, 0, '*He works*, *she goes*.', 7),
    ('ad149d3d-019f-5a09-8f0c-699534dd4c97'::uuid, 'fa763ba5-d984-589f-bf13-3e0f9e423169'::uuid, '« I’m thinking about it » et « I think it’s good » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier décrit une activité en cours, le second une opinion.', 8),
    ('99d63f78-3922-5960-af8b-16d8b49d3b7a'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, 'Comment se forme le prétérit d’un verbe régulier ?', 'mcq', '["Base + -ed","Base + -ing","have + participe passé","was + base"]'::jsonb, 0, '*Work → worked*, *play → played*.', 1),
    ('f294c5c6-2d69-55ef-8843-81d308fb9ea8'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, '« I didn’t went » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Did* porte déjà le passé : *I didn’t go.*', 2),
    ('5ee77a47-468c-5a49-a3f6-1dd56ecc9d1c'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, 'Quel temps pour « I saw him yesterday » ?', 'mcq', '["Le prétérit","Le present perfect","Le past perfect","Le présent simple"]'::jsonb, 0, 'Un repère de temps passé impose le prétérit.', 3),
    ('9db674bb-797c-56fd-854d-99f8cdaefb50'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, '« I have seen him yesterday » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le present perfect refuse tout repère de passé daté.', 4),
    ('2af175eb-fb30-5bcb-b3b0-a0791a761414'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, 'Dans « I was watching TV when the phone rang », le prétérit en BE + -ING décrit…', 'mcq', '["L’action en cours, interrompue","L’action brève qui interrompt","Une habitude passée","Un futur dans le passé"]'::jsonb, 0, 'C’est l’arrière-plan ; *rang* est l’événement.', 5),
    ('74f78d06-63a9-5c88-8156-e2d586ed8a80'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, 'Le prétérit établit un lien avec le moment présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il coupe au contraire du présent : c’est ce qui le distingue du present perfect.', 6),
    ('3b723948-eaca-50e3-9fa2-0093e7674bd8'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, 'Quel est le prétérit de « take » ?', 'mcq', '["took","taked","taken","takes"]'::jsonb, 0, 'Verbe irrégulier : *take – took – taken*.', 7),
    ('0f934c2f-205f-5c6b-8f08-10add06e3bf2'::uuid, '3557990f-ffd2-5bae-9e89-f2476bdaecc1'::uuid, '« When I was a child » appelle le prétérit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un repère de passé révolu.', 8),
    ('be3029ad-57f5-5881-b6cb-5976cda200de'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, 'Comment se forme le present perfect ?', 'mcq', '["have/has + participe passé","had + participe passé","be + -ing","did + base verbale"]'::jsonb, 0, '*I have finished*, *she has gone*.', 1),
    ('4f1d034e-eacd-57de-a205-343ce62fc76f'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, 'Comment traduit-on « Je vis ici depuis 2019 » ?', 'mcq', '["I have lived here since 2019","I live here since 2019","I am living here since 2019","I lived here since 2019"]'::jsonb, 0, 'Une situation commencée dans le passé et toujours vraie appelle le present perfect.', 2),
    ('218fc7ec-4a71-5a48-ac3c-414364c4b5d0'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, '« Since » introduit une durée, « for » un point de départ.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : *since 2019* (point de départ), *for six years* (durée).', 3),
    ('30b610b4-6b13-5dc1-9f61-83278afe8832'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, '« I have lost my keys » insiste sur…', 'mcq', '["Le résultat présent : je ne les ai plus","Le moment exact de la perte","Une habitude","Un projet"]'::jsonb, 0, 'Le present perfect fait le bilan au présent.', 4),
    ('2d75ef80-de3f-5bb4-9359-8e369614bca9'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, 'Quel marqueur va avec le present perfect ?', 'mcq', '["already","yesterday","last week","in 2010"]'::jsonb, 0, 'Les repères datés imposent au contraire le prétérit.', 5),
    ('2797b8fe-3730-5d26-911b-4abcc1c123d9'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, '« I’ve been waiting for two hours » suggère que l’attente est terminée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme en -ING insiste sur la durée en cours.', 6),
    ('ea17f8d8-7661-522d-bc06-ce08c3367d4a'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, '« Have you ever been to London? » interroge sur…', 'mcq', '["Une expérience de vie, sans date","Un voyage précis daté","Un projet futur","Une habitude actuelle"]'::jsonb, 0, '*Ever* est un marqueur typique du bilan d’expérience.', 7),
    ('feabb13b-1b0b-54b6-b96e-e43cf10ca875'::uuid, 'd5a389b9-41f9-5172-bed7-1fa51f45a6de'::uuid, '« I have finished yesterday » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un repère daté est incompatible avec le present perfect.', 8),
    ('20239dae-5450-5c06-ad8a-4799888c990d'::uuid, '2e2fac2a-f993-56be-a9cd-02c325df1d1e'::uuid, 'Comment se forme le past perfect ?', 'mcq', '["had + participe passé","have + participe passé","was + -ing","did + participe passé"]'::jsonb, 0, 'La forme est la même à toutes les personnes.', 1),
    ('a16ba30f-0cdc-5a6a-b172-31a7148e25bd'::uuid, '2e2fac2a-f993-56be-a9cd-02c325df1d1e'::uuid, 'Dans « When I arrived, the train had already left », quel fait est le plus ancien ?', 'mcq', '["Le départ du train","Mon arrivée","Les deux sont simultanés","On ne peut pas le savoir"]'::jsonb, 0, 'Le past perfect marque l’antériorité.', 2),
    ('440872b3-b000-5080-b19f-379a4ee3d18c'::uuid, '2e2fac2a-f993-56be-a9cd-02c325df1d1e'::uuid, 'Le past perfect correspond souvent au plus-que-parfait français.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Il avait fini* → *he had finished*.', 3),
    ('3c637e48-acc2-5cb5-8354-249de08a45a7'::uuid, '2e2fac2a-f993-56be-a9cd-02c325df1d1e'::uuid, 'Au discours indirect, un prétérit devient…', 'mcq', '["Un past perfect","Un present perfect","Un présent","Un futur"]'::jsonb, 0, 'Comme le present perfect : les deux remontent à *had* + participe passé.', 4),
    ('d880a896-b73a-5a74-bc21-77e598aea7f1'::uuid, '2e2fac2a-f993-56be-a9cd-02c325df1d1e'::uuid, '« He had been driving for ten hours » insiste sur…', 'mcq', '["La durée de l’action antérieure","Le résultat achevé","Une habitude présente","Un projet"]'::jsonb, 0, '*Had been* + -ING met la durée en avant.', 5),
    ('0c587914-1d8f-5d48-ad92-99634c3c0c01'::uuid, '2e2fac2a-f993-56be-a9cd-02c325df1d1e'::uuid, 'Le past perfect s’emploie aussi dans l’irréel du passé après « if ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*If I had known, I would have come.*', 6),
