    ('b634b7be-e191-5180-8f73-15b93eb480d7'::uuid, '173609dc-5507-5057-a5b5-3389a75646c5'::uuid, '« I had the mechanic check the brakes » implique…', 'mcq', '["Une demande à quelqu’un dont c’est le métier","Une contrainte violente","Une permission accordée","Une interdiction"]'::jsonb, 0, '*Have* + complément + base verbale, sans contrainte.', 8),
